SELECT budget_bucket, sales_budget FROM (SELECT CASE WHEN budget >= 3987000 THEN 'high' WHEN budget >= 605000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(CASE WHEN dept_name = 'Sales' THEN budget ELSE 0 END) AS sales_budget FROM departments WHERE budget BETWEEN 2913000 AND 3369000 GROUP BY CASE WHEN budget >= 3987000 THEN 'high' WHEN budget >= 605000 THEN 'mid' ELSE 'low' END) AS x WHERE sales_budget >= 73 ORDER BY budget_bucket DESC;
